function delay(ms) {
  return new Promise(function (resolve) {
    setTimeout(resolve, ms);
  });
}
async function waitFor(condition, timeoutMs) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    if (condition()) {
      return true;
    }
    await delay(50);
  }
  return false;
}
async function run() {
  const ok = await waitFor(function () {
    return true;
  }, 1000);
  console.log('condition met: ' + ok);
}
run();

async function waitForText(query, target, timeoutMs) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const el = document.querySelector(query);
    if (el && el.textContent.includes(target)) {
      return true;
    }
    await new Promise(function (r) {
      setTimeout(r, 50);
    });
  }
  return false;
}
waitForText('h1', 'Done').then(function (ok) {
  console.log('element reached expected state: ' + ok);
