async function withRetry(fn, attempts) {
  let lastError = null;
  for (let i = 1; i <= attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError;
}
async function run() {
  let tries = 0;
  const value = await withRetry(async function () {
    tries = tries + 1;
    if (tries < 3) {
      throw new Error('temporary 502');
    }
    return 'healthy';
  }, 5);
  console.log('succeeded after ' + tries + ' tries with value ' + value);
}
run();

